<script type="module">
import * as THREE from 'three';

const renderer = new THREE.WebGLRenderer({ preserveDrawingBuffer: true });
renderer.setPixelRatio(1);
renderer.setSize(240,242);
renderer.setClearColor(0xc6b7a2);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
const V = (x,y,z) => new THREE.Vector3(x,y,z);
const angle = .337, cs = Math.cos(angle), sn = Math.sin(angle);
const view = V(0,sn,cs);
const ref = new THREE.OrthographicCamera(-120,120,121,-121,1,1800);
ref.position.copy(V(0,110,0)).addScaledVector(view,800);
ref.lookAt(0,110,0);
ref.updateMatrixWorld();
function point(x,y,z) { return V(x-120,110+(121-y+z*sn)/cs,z); }
function group(parent,name) {
  const g = new THREE.Group();
  g.name = name; parent.add(g); return g;
}
let seed = 843895;
function random() { seed=(Math.imul(seed,1664525)+1013904223)>>>0; return seed/4294967296; }
function material(color,roughness=.88) {
  return new THREE.MeshStandardMaterial({color,roughness});
}
function mesh(parent,name,geometry,mat) {
  const m = new THREE.Mesh(geometry,mat);
  m.name=name; m.castShadow=true; m.receiveShadow=true;
  parent.add(m); return m;
}
const ball = new THREE.SphereGeometry(1,40,28);
function ell(parent,name,pos,scale,mat) {
  const obj=mesh(parent,name,ball,mat);
  obj.position.copy(pos); obj.scale.set(...scale); return obj;
}
function box(parent,name,pos,size,mat) {
  const m=mesh(parent,name,new THREE.BoxGeometry(...size),mat);
  m.position.copy(pos); return m;
}
function between(parent,name,a,b,r1,r2,mat) {
  const d=b.clone().sub(a);
  const m=mesh(parent,name,new THREE.CylinderGeometry(r2,r1,d.length(),18),mat);
  m.position.copy(a).lerp(b,.5);
  m.quaternion.setFromUnitVectors(V(0,1,0),d.normalize()); return m;
}
function surface(parent,name,nu,nv,sample,mat,reverse=false) {
  const xyz=[],col=[],uv=[],idx=[];
  for(let j=0;j<=nv;j++) for(let i=0;i<=nu;i++) {
    const s=sample(i/nu,j/nv);
    xyz.push(s.p.x,s.p.y,s.p.z); uv.push(i/nu,j/nv);
    if(s.c) col.push(s.c.r,s.c.g,s.c.b);
    if(i<nu && j<nv) {
      const a=j*(nu+1)+i,b=a+1,d=a+nu+1,e=d+1;
      if(reverse)idx.push(a,d,b,b,d,e); else idx.push(a,b,d,b,e,d);
    }
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(xyz,3));
  geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
  if(col.length) geo.setAttribute('color',new THREE.Float32BufferAttribute(col,3));
  geo.setIndex(idx);geo.computeVertexNormals();
  return mesh(parent,name,geo,mat);
}
function mapTexture(kind) {
  const n=64,data=new Uint8Array(n*n*4);
  const line=Array.from({length:n},()=>random());
  for(let y=0;y<n;y++) for(let x=0;x<n;x++) {
    const i=4*(y*n+x),r=random();
    if(kind==='wood') {
      const w=Math.floor(y+1.6*Math.sin(x/64*2*Math.PI+y*.14)+64)%64;
      const k= .84+.13*line[w]+.035*r;
      data[i]=255*k;data[i+1]=250*k;data[i+2]=237*k;
    } else {
      const k=Math.floor(213+42*r);
      data[i]=k; data[i+1]=k; data[i+2]=k;
    }
    data[i+3]=255;
  }
  const t=new THREE.DataTexture(data,n,n);
  t.wrapS=t.wrapT=THREE.RepeatWrapping;
  t.magFilter=THREE.LinearFilter;t.minFilter=THREE.LinearMipmapLinearFilter;
  t.generateMipmaps=true;t.colorSpace=THREE.SRGBColorSpace;
  t.repeat.set(kind==='wood'?1.5:4,kind==='wood'?1.6:3);
  t.needsUpdate=true;return t;
}
const nap=mapTexture('nap'),woodGrain=mapTexture('wood');
function fabric(color,vertexColors=false) {
  const m=new THREE.MeshStandardMaterial({color,vertexColors,map:nap,bumpMap:nap,bumpScale:.16,roughness:1});
  m.side=THREE.DoubleSide;return m;
}
const gold=fabric(0xffb927),fingerMat=fabric(0x756249);
const coat=fabric(0xffffff,true);
const goldColor=new THREE.Color(0xffbd2b),creamColor=new THREE.Color(0xffe6ba);
const darkMouth=material(0x3e2819),softMouth=material(0x95621f);
const sclera=material(0xa5987e,.78),iris=material(0x443c32,.58),pupil=material(0x1d1916,.4);
const glint=material(0xbdb29b,.5);
function cubic(a,b,c,d,t) {
  return b+.5*t*(c-a+t*(2*a-5*b+4*c-d+t*(3*b-a-3*c+d)));
}
function sampleRows(rows,v) {
  const f=THREE.MathUtils.clamp(v,0,1)*(rows.length-1),i=Math.min(rows.length-2,Math.floor(f)),t=f-i;
  return rows[i].map((b,k)=>cubic(rows[Math.max(0,i-1)][k],b,rows[i+1][k],rows[Math.min(rows.length-1,i+2)][k],t));
}
function sweep(parent,name,rows,mat) {
  const path=rows.map(q=>point(q[0],q[1],q[2]));
  const curve=new THREE.CatmullRomCurve3(path,false,'catmullrom',.4);
  const r=rows.map(q=>[q[3],q[4]??q[3]]);
  const n=Math.max(22,rows.length*7),frames=curve.computeFrenetFrames(n,false);
  return surface(parent,name,28,n,(u,v)=>{
    const j=Math.round(v*n),p=curve.getPointAt(v),t=curve.getUtoTmapping(v);
    const [a,b]=sampleRows(r,t),phi=2*Math.PI*u;
    p.addScaledVector(frames.normals[j],Math.max(.06,a)*Math.cos(phi));
    p.addScaledVector(frames.binormals[j],Math.max(.06,b)*Math.sin(phi));
    return {p};
  },mat);
}
function loft(character,head,name,rows,split,bellyTop,bellyDirection) {
  const parts=[];
  function vertex(u,t) {
    const [x,y,z,rx,rz]=sampleRows(rows,t),a=(u-.5)*Math.PI*2;
    const p=point(x,y,z);
    p.x+=Math.max(.04,rx)*Math.sin(a);
    p.z+=Math.max(.04,rz)*Math.cos(a);
    const phi=Math.atan2(Math.sin(a-bellyDirection),Math.cos(a-bellyDirection));
    const patch=1-(phi/1.26)**2-((y-(bellyTop+52))/52)**2;
    const w=THREE.MathUtils.smoothstep(patch,-.045,.06);
    const c=goldColor.clone().lerp(creamColor,w);
    return {p,c};
  }
  for(const [owner,label,lo,hi] of [[head,'crown and cheeks',0,split],[character,'chest and belly',split,1]]) {
    const m=surface(owner,label,112,72,(u,v)=>vertex(u,lo+(hi-lo)*v),coat,true);
    const normal=m.geometry.attributes.normal;
    for(let j=0;j<=72;j++) for(let i=0;i<=112;i++) {
      const u=i/112,t=lo+(hi-lo)*j/72;
      const dx=vertex(u+.0002,t).p.sub(vertex(u-.0002,t).p);
      const dy=vertex(u,Math.min(1,t+.0002)).p.sub(vertex(u,Math.max(0,t-.0002)).p);
      const n=dy.cross(dx).normalize();normal.setXYZ(j*113+i,n.x,n.y,n.z);
    }
    parts.push(m);
  }
  character.updateMatrixWorld(true);return parts;
}
const ray=new THREE.Raycaster();
function facePoint(parts,x,y,raise=0) {
  ray.set(point(x,y,260),view.clone().negate());
  const hit=ray.intersectObjects(parts,false)[0];
  return (hit?hit.point:point(x,y,-25)).addScaledVector(view,raise);
}
function eye(head,parts,name,x,y,r,normal,gaze) {
  const g=group(head,name);
  g.position.copy(facePoint(parts,x,y,.35));
  g.quaternion.setFromUnitVectors(V(0,0,1),normal.normalize());
  ell(g,'soft eye surround',V(0,0,-.5),[r*1.03,r*1.04,r*.70],sclera);
  ell(g,'iris',V(gaze*r,-r*.105,r*.38),[r*.745,r*.805,r*.51],iris);
  ell(g,'pupil',V(gaze*r*1.25,-r*.15,r*.64),[r*.586,r*.635,r*.37],pupil);
  ell(g,'reflected light',V(gaze*r-.19*r,.19*r,r*.93),[r*.085,r*.068,r*.05],glint);
  return g;
}
function smile(head,parts,right) {
  const g=group(head,'mouth');
  const m=right?darkMouth:softMouth;
  m.side=THREE.DoubleSide;
  surface(g,'curved mouth opening',36,6,(u,v)=>{
    const x=right?121.7+22*u:63.6+16*u;
    const y=right?86.3+1.8*u+1.0*Math.sin(Math.PI*u):109.8+1.2*u+1.8*Math.sin(Math.PI*u);
    const h=Math.pow(Math.max(.0001,Math.sin(Math.PI*u)),.73)*(right?3.2:1.55);
    return {p:facePoint(parts,x,y+h*v,.46+.23*Math.sin(Math.PI*v))};
  },m);
}
