      const f=k/5;
      surface(g,'layer of paper',26,2,(u,v)=>({p:pagePos(side,u*(1.008-.008*f),v+.008*(1-f),.12+f*arch(u,v))}),k%2?paper:pageEdge,side>0);
    }
    surface(g,'open cream page',42,12,(u,v)=>({p:pagePos(side,u,v,arch(u,v))}),side<0?paper:paper2,side>0);
    for(let i=0;i<4;i++){
      const u=.76+.048*i;
      const a=pagePos(side,u,.90,arch(u,.9)+.07),b=pagePos(side,u+.09,.90,arch(u+.09,.9)+.07);
